import random
import ipaddress

# Generate valid textual IP address strings with optional port, including
# IPv4, IPv6 (with brackets), IPv4-mapped IPv6, and edge cases like wildcard
# and localhost. Return as bytes to seed FUZZ_PARAM_STR consumers.

MAX_LEN = 4096

COMMON_HOSTS = [
    "0.0.0.0",
    "127.0.0.1",
    "255.255.255.255",
    "::",
    "::1",
    "2001:db8::1",
    "fe80::1",
    "ffff:ffff:ffff:ffff:ffff:ffff:ffff:ffff",
]

COMMON_PORTS = [0, 1, 7, 9, 13, 17, 19, 20, 21, 22, 23, 25, 37, 53, 67, 68, 69,
                80, 110, 111, 123, 135, 137, 138, 139, 143, 161, 162, 179, 194,
                389, 443, 445, 465, 514, 515, 587, 631, 993, 995, 1080, 1194,
                1433, 1521, 1723, 2049, 2181, 2379, 3000, 3306, 3389, 5000,
                5432, 5631, 5900, 6379, 7001, 8000, 8080, 8443, 9000, 11211,
                27017, 32768, 49152, 65535]


def _rand_port(r: random.Random) -> int:
    if r.random() < 0.7:
        return r.choice(COMMON_PORTS)
    return r.randint(0, 65535)


def _maybe_port(r: random.Random) -> str:
    if r.random() < 0.75:
        return str(_rand_port(r))
    return ""


def _ipv4_random(r: random.Random) -> str:
    # Bias toward interesting octets
    octet_pool = [0, 1, 10, 127, 169, 172, 192, 198, 224, 239, 255]
    parts = []
    for _ in range(4):
        if r.random() < 0.6:
            parts.append(str(r.choice(octet_pool)))
        else:
            parts.append(str(r.randint(0, 255)))
    return ".".join(parts)


def _ipv6_random(r: random.Random) -> str:
    # Generate random IPv6; sometimes compress, sometimes full
    if r.random() < 0.25:
        # IPv4-mapped IPv6
        v4 = _ipv4_random(r)
        return "::ffff:" + v4
    # Build 8 hextets; then apply zero-compression heuristics
    hextets = []
    for _ in range(8):
        if r.random() < 0.4:
            hextets.append(hex(r.choice([0, 1, 0xffff, 0x7fff, 0x8000]))[2:])
        else:
            hextets.append(hex(r.randint(0, 0xffff))[2:])
    # Normalize without leading zero padding; compress a random run of zeros
    if r.random() < 0.7:
        # find zero runs
        runs = []
        start = None
        for i, h in enumerate(hextets + [None]):
            if h == "0":
                if start is None:
                    start = i
            else:
                if start is not None:
                    runs.append((start, i - 1))
                    start = None
        if runs:
            s, e = max(runs, key=lambda t: (t[1]-t[0], -t[0]))
            # replace with ::
            left = ":".join(hextets[:s])
            right = ":".join(hextets[e+1:])
            if left and right:
                return f"{left}::{right}"
            elif left:
                return f"{left}::"
            elif right:
                return f"::{right}"
            else:
                return "::"
    return ":".join(hextets)


def _format_with_port(r: random.Random, host: str, is_ipv6: bool) -> str:
    port = _maybe_port(r)
    if is_ipv6:
        # For IPv6 with port, RFC requires brackets
        if port:
            return f"[{host}]:{port}"
        # Without port, brackets are optional but sometimes used; vary
        if r.random() < 0.3:
            return f"[{host}]"
        return host
    else:
        if port:
            return f"{host}:{port}"
        return host


def _valid_ip_texts(r: random.Random) -> list[str]:
    out = []
    # Fixed interesting samples
    fixed = [
        "1.2.3.4",
        "1.2.3.4:80",
        "0.0.0.0",
        "255.255.255.255:65535",
        "127.0.0.1:0",
        "[::1]",
        "[::1]:443",
        "[2001:db8::1]",
        "[2001:db8::1]:8080",
        "[::]",
        "[::ffff:192.0.2.1]:25",
    ]
    out.extend(fixed)

    # Random IPv4/IPv6 variants
    for _ in range(r.randint(5, 12)):
        host4 = _ipv4_random(r)
        out.append(_format_with_port(r, host4, is_ipv6=False))
    for _ in range(r.randint(5, 12)):
        host6 = _ipv6_random(r)
        out.append(_format_with_port(r, host6, is_ipv6=True))

    # Validate with ipaddress where applicable (without ports/brackets)
    validated = []
    for s in out:
        try:
            if s.startswith("["):
                # strip brackets and optional :port
                if "]:" in s:
                    core = s[1:s.index("]:")]
                else:
                    core = s[1:-1] if s.endswith("]") else s[1:]
                ipaddress.ip_address(core)
            else:
                if ":" in s and s.count(":") == 1 and "]" not in s:
                    host, port = s.rsplit(":", 1)
                    int(port)
                    ipaddress.ip_address(host)
                else:
                    ipaddress.ip_address(s)
            validated.append(s)
        except Exception:
            # If validation fails (e.g., compressed form parsing issue), skip
            pass

    # Ensure at least some entries; fall back to guaranteed-valid set
    if not validated:
        validated = fixed
    # Deduplicate while preserving order
    seen = set()
    res = []
    for s in validated:
        if s not in seen:
            seen.add(s)
            res.append(s)
    return res


def _pack_corpus(entries: list[str]) -> bytes:
    # Simple length-prefixed strings corpus to feed multiple FUZZ_PARAM_STR calls
    # Format: 32-bit count (LE), then for each entry: 16-bit length (LE) + bytes
    # The harness can slice or reuse FUZZ data; we provide a compact list.
    from struct import pack
    buf = bytearray()
    n = min(len(entries), 256)
    buf += pack("<I", n)
    for s in entries[:n]:
        b = s.encode("ascii", errors="ignore")
        b = b[:65535]
        buf += pack("<H", len(b))
        buf += b
    return bytes(buf[:MAX_LEN])


def generate(seed: int) -> bytes:
    r = random.Random(seed)
    # Mix in seed jitter for diversity across calls
    jitter = r.getrandbits(32)
    r.seed((seed ^ jitter) & 0xFFFFFFFF)

    entries = _valid_ip_texts(r)

    # Add a few boundary ports for some entries
    extras = []
    for host in COMMON_HOSTS:
        if ":" in host:  # IPv6 literal
            extras.append(f"[{host}]:0")
            extras.append(f"[{host}]:65535")
        else:
            extras.append(f"{host}:0")
            extras.append(f"{host}:65535")
    entries.extend(extras)

    # Shuffle for variety
    r.shuffle(entries)

    return _pack_corpus(entries)

import random
import string
from typing import List

# Data type: hostname string
# Used by stubs:
# - evutil_getaddrinfo: FUZZ_PARAM_STR() for node and service (may be NULL depending on size modulo)
# - evdns_cache_lookup: FUZZ_PARAM_STR() for node (must be non-empty). Numeric host allowed; hints may constrain family.
# - evdns_cache_write: FUZZ_PARAM_STR() for nodename (must be non-empty, mutable C string).
# - evhttp_add_virtual_host: FUZZ_PARAM_STR() for hostname glob pattern (can be "*", limited length)
# - evhttp_add_server_alias / remove: FUZZ_PARAM_STR() hostname-like alias (non-empty; trimmed length)
# - evhttp_uri_set_host: FUZZ_PARAM_STR() host component (bounded length; may be cleared)
#
# Strategy: Generate a single buffer containing one or more newline-separated candidate strings so that
# FUZZ_PARAM_STR() pulls interesting, valid host-like values. We will include a mix of:
# - Regular domain names with various labels
# - IDNA-like punycode labels (ascii only)
# - Numeric IPv4 addresses (dotted-quad)
# - Numeric IPv6 addresses in different forms (full, compressed, with scope id, with port-like service in later pulls)
# - Host globs usable by evhttp_add_virtual_host (e.g., *.example.com, ? wildcards)
# - Localhost and single-label hosts
# - Internationalized-looking but ascii-safe labels (xn-- punycode prefix)
# - Service names for getaddrinfo (e.g., http, https, 0-65535 numeric). Although service uses a separate FUZZ_PARAM_STR,
#   we place service-like tokens too so subsequent pulls can get them.
# The buffer must be <=4096 bytes.

LABEL_CHARS = string.ascii_lowercase + string.digits + "-"

def rand_label(rng: random.Random, min_len=1, max_len=20) -> str:
    # DNS label rules: 1-63 chars, letters/digits/hyphen, cannot start or end with hyphen.
    L = rng.randint(min_len, min(20, max_len))
    if L == 1:
        return rng.choice(string.ascii_lowercase + string.digits)
    inner_len = L - 2
    inner = ''.join(rng.choice(LABEL_CHARS) for _ in range(inner_len))
    start = rng.choice(string.ascii_lowercase + string.digits)
    end = rng.choice(string.ascii_lowercase + string.digits)
    return start + inner + end

def rand_domain(rng: random.Random) -> str:
    # 2-5 labels plus a common TLD
    tlds = ["com","net","org","io","dev","local","example"]
    nlabels = rng.randint(2, 5)
    labels = [rand_label(rng) for _ in range(nlabels-1)] + [rng.choice(tlds)]
    return '.'.join(labels)

def rand_ipv4(rng: random.Random) -> str:
    return '.'.join(str(rng.randint(0,255)) for _ in range(4))

def rand_hextet(rng: random.Random) -> str:
    return format(rng.randint(0, 0xFFFF), 'x')

def rand_ipv6_full(rng: random.Random) -> str:
    return ':'.join(rand_hextet(rng) for _ in range(8))

def rand_ipv6_compressed(rng: random.Random) -> str:
    # generate 8 hextets, insert one :: compression by replacing a run of zeros
    hextets = [rand_hextet(rng) if rng.random() < 0.7 else '0' for _ in range(8)]
    # ensure at least one zero run to compress
    if all(h != '0' for h in hextets):
        hextets[rng.randrange(8)] = '0'
    # find a maximal zero run
    max_run = (0, -1)
    i = 0
    while i < 8:
        if hextets[i] == '0':
            j = i
            while j < 8 and hextets[j] == '0':
                j += 1
            if j - i > max_run[1] - max_run[0]:
                max_run = (i, j)
            i = j
        else:
            i += 1
    a, b = max_run
    left = ':'.join(hextets[:a])
    right = ':'.join(hextets[b:])
    if left and right:
        return left + '::' + right
    elif left:
        return left + '::'
    elif right:
        return '::' + right
    else:
        return '::'

def rand_glob(rng: random.Random) -> str:
    # Patterns like *.example.com, foo?.bar, *
    choices = [
        "*",
        "*." + rand_domain(rng),
        rand_label(rng) + ".*",
        rand_label(rng) + "?" + "." + rand_domain(rng),
        "*." + rand_label(rng) + "." + rng.choice(["com","net","org"]),
    ]
    return rng.choice(choices)

def rand_service(rng: random.Random) -> str:
    services = ["http", "https", "ssh", "domain", "smtp"]
    if rng.random() < 0.5:
        return rng.choice(services)
    else:
        return str(rng.randint(0, 65535))

def maybe_suffix_port(rng: random.Random, host: str) -> str:
    # For cases where a service string might be consumed separately, we keep host standalone.
    # But occasionally produce host:port to exercise parsers that accept it (evhttp may not use this, safe as string).
    if rng.random() < 0.25:
        return host + ":" + str(rng.randint(0,65535))
    return host

def make_candidates(rng: random.Random) -> List[str]:
    cands: List[str] = []
    # Hostnames
    for _ in range(rng.randint(3,6)):
        cands.append(rand_domain(rng))
    # IPv4 and IPv6
    for _ in range(rng.randint(2,4)):
        cands.append(rand_ipv4(rng))
    cands.append(rand_ipv6_full(rng))
    cands.append(rand_ipv6_compressed(rng))
    # IPv6 with scope id (for link-local style)
    cands.append(rand_ipv6_compressed(rng) + "%" + rng.choice(["eth0","1","en0"]))
    # Common hosts
    cands += ["localhost", "127.0.0.1", "::1", "xn--exmple-cua.com", "intranet", "example.com"]
    # Globs for virtual hosts
    for _ in range(3):
        cands.append(rand_glob(rng))
    # Occasionally empty string to allow stubs that handle NULL by size%N checks; but we must ensure non-empty exists too.
    if rng.random() < 0.2:
        cands.append("")
    # Service-like tokens for getaddrinfo's separate service parameter
    for _ in range(4):
        cands.append(rand_service(rng))
    # Maybe host:port variants
    for _ in range(3):
        cands.append(maybe_suffix_port(rng, rand_domain(rng)))
    # Bound length and reasonable uniqueness
    uniq = []
    seen = set()
    for s in cands:
        if s in seen:
            continue
        seen.add(s)
        # Trim overly long strings to 128 as used by evhttp_uri_set_host bounds
        if len(s) > 128:
            s = s[:128]
        uniq.append(s)
    return uniq

def generate(seed: int) -> bytes:
    rng = random.Random(seed)
    cands = make_candidates(rng)
    # Shuffle to vary which strings are pulled first by FUZZ_PARAM_STR
    rng.shuffle(cands)
    # Join with newlines so each FUZZ_PARAM_STR() can read a distinct slice from provider.
    # Also include some CRLF and NUL-terminated variants inline to exercise parsers that stop at NUL.
    parts: List[bytes] = []
    for s in cands:
        # Randomly choose a line ending
        ending = rng.choice(["\n", "\r\n", "\n", "\n"])  # bias to \n
        bs = s.encode('ascii', errors='ignore')
        # Occasionally append a NUL to ensure safe C-string terminators for text frames if used
        if rng.random() < 0.1:
            bs += b"\x00"
        parts.append(bs + ending.encode('ascii'))
    data = b''.join(parts)
    # Ensure not exceeding 4096 bytes
    return data[:4096]
